<?php use App\Core\Csrf; ?><header class="page-header compact"><div><a class="back-link" href="/emails">← Email Centre</a><div class="eyebrow"><?= htmlspecialchars((string)$template['template_key']) ?></div><h1><?= htmlspecialchars((string)$template['name']) ?></h1><p>Edit the subject and HTML content. Template variables use double curly brackets.</p></div></header><?php if($flash): ?><div class="alert <?= htmlspecialchars($flash['type']) ?>"><?= htmlspecialchars($flash['message']) ?></div><?php endif; ?><form class="record-form email-template-form" method="post" action="/emails/templates/<?= (int)$template['id'] ?>"><input type="hidden" name="_token" value="<?= htmlspecialchars(Csrf::token()) ?>"><section class="form-card"><label>Subject<input name="subject" value="<?= htmlspecialchars((string)$template['subject']) ?>" required></label><label>Email HTML<textarea name="body_html" rows="18" required><?= htmlspecialchars((string)$template['body_html']) ?></textarea></label><label class="toggle-field"><input type="checkbox" name="enabled" value="1" <?= $template['enabled']?'checked':'' ?>><span><strong>Template enabled</strong><small>Allow automatic and manual delivery.</small></span></label></section><section class="variable-card"><strong>Available variables</strong><code>{{customer_name}} {{customer_email}} {{portal_url}} {{temporary_password}} {{order_number}} {{order_description}} {{order_total}} {{order_status}} {{invoice_number}} {{invoice_total}} {{invoice_due_date}} {{invoice_url}} {{payment_amount}} {{invoice_balance}}</code></section><div class="form-actions"><a class="secondary-button" href="/emails">Cancel</a><button class="primary-button">Save template</button></div></form>
